const band = (dir) => {
  const g = new THREE.Group();
  g.position.copy(T(0, 0.98, 0));
  g.rotation.z = dir * 0.62;
  // A continuous ribbon runs over the shoulder, down the chest and around the back.
  const curve=new THREE.CatmullRomCurve3([[0,-.33,.14],[0,-.27,.225],[0,0,.255],[0,.215,.22],[0,.238,.08],[0,.218,-.15],[0,0,-.16],[0,-.31,-.14],[0,-.35,0]].map(p=>new THREE.Vector3(...p)),true);
  const pos=[],uv=[],ix=[],n=64;
  for(let j=0;j<=n;j++){const t=j/n,c=curve.getPointAt(t),d=curve.getTangentAt(t),normal=new THREE.Vector3(0,-d.z,d.y);for(const[s,h]of[[-1,-1],[1,-1],[-1,1],[1,1]]){const p=c.clone().addScaledVector(normal,h*.0035);p.x+=s*.03;pos.push(p.x,p.y,p.z);uv.push(s*.5+.5,t*8);}}
  for(let j=0;j<n;j++)for(const[a,b]of[[0,1],[1,3],[3,2],[2,0]]){const x=j*4+a,y=j*4+b;ix.push(x,y,x+4,y,y+4,x+4);}
  const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geo.setIndex(ix);geo.computeVertexNormals();g.add(addCast(new THREE.Mesh(geo,webMat)));
  for(let j=0;j<10;j++){const y=-.27+j*.054;put(g,rmesh(.065,.012,.012,strapMat,.003),0,y,.255-.035*(y/.24)**2);}
  put(g,rmesh(.074,.043,.015,buckleMat,.005),0,-.235,.24);
  put(g,rmesh(.052,.026,.016,webMat,.003),0,-.235,.249);
  mergeRigidMeshes(g,{},new Set());
  torso.add(g);
  return g;
};
rig.bandolier = band(-1);
rig.shells = carryInstanced(new THREE.CylinderGeometry(0.011, 0.011, 0.05, 8), carryMats.shell, CARRY_SLOTS.shells, (o, i) => { const y=-.27+i*.054;o.position.set(0,y,.27-.035*(y/.24)**2); o.rotation.z = Math.PI / 2; });
rig.bandolier.add(rig.shells);
rig.belt40 = band(1);
rig.rounds40 = carryInstanced(new THREE.CylinderGeometry(0.02, 0.02, 0.045, 10), carryMats.brass, CARRY_SLOTS.rounds40, (o, i) => { const y=-.25+i*.09;o.position.set(0,y,.279-.035*(y/.24)**2);o.rotation.z=Math.PI/2; });
rig.belt40.add(rig.rounds40);

  // Over the carrier the bands and tops sit further out than on the shirt.
  const z = p.vest ? 0 : -0.045;
  rig.bandolier.position.z = z; rig.belt40.position.z = z + 0.012;
}
